MUTATIONS = [
    ("pull ignores untracked files", '[ -z "$(git status --porcelain --untracked-files=all -- etc-nginx)" ] && git diff', 'git diff --quiet && git diff'),
    ("pull ignores staged changes", 'etc-nginx)" ] && git diff --cached --quiet \\', 'etc-nginx)" ] \\'),
    ("pull keeps dash-www", 'rsync -a --delete --exclude=/dash-www "$host:/etc/nginx/"', 'rsync -a --delete "$host:/etc/nginx/"'),
    ("pull without --delete", 'rsync -a --delete --exclude=/dash-www "$stash/" etc-nginx/', 'rsync -a --exclude=/dash-www "$stash/" etc-nginx/'),
    ("stash not removed on refusal", 'push or discard them first" >&2; rm -rf "$stash"; return 1; }', 'push or discard them first" >&2; return 1; }'),
    ("push with --delete", 'rsync -rl --checksum --omit-dir-times --no-perms --no-times etc-nginx/ "$host:/etc/nginx/"; then', 'rsync -rl --delete --checksum --omit-dir-times --no-perms --no-times etc-nginx/ "$host:/etc/nginx/"; then'),
    ("push stages tracked only", '    git add -A etc-nginx\n    git diff --cached --quiet && { echo "nothing to push"', '    git add -u etc-nginx\n    git diff --cached --quiet && { echo "nothing to push"'),
    ("copy failure keeps the commit", '      git reset -q --soft HEAD~1\n', '      :\n'),
    ("copy failure exits 0", 'run \'proxy test\'." >&2\n      exit 1', 'run \'proxy test\'." >&2\n      exit 0'),
    ("nginx -t stderr dropped", "'sudo -n /usr/sbin/nginx -t' 2>&1 | tail -2 | grep", "'sudo -n /usr/sbin/nginx -t' 2>/dev/null | tail -2 | grep"),
    ("reload skipped", "ssh \"$host\" 'sudo -n /usr/bin/systemctl reload nginx' && {", "true && {"),
    ("reload failure exits 0", 'check \'proxy test\' and the VM." >&2\n      exit 1', 'check \'proxy test\' and the VM." >&2\n      exit 0'),
    ("reload failure message gone", '      echo "proxy: nginx -t passed but the reload FAILED', '      : "proxy: nginx -t passed but the reload FAILED'),
    ("rollback: no revert", 'if git revert --no-edit HEAD >/dev/null && rsync', 'if true && rsync'),
    ("rollback: no copy back", ' && rsync -rl --checksum --omit-dir-times --no-perms --no-times etc-nginx/ "$host:/etc/nginx/" \\\n', ' \\\n'),
    ("rollback: no verify", "         && ssh \"$host\" 'sudo -n /usr/sbin/nginx -t' >/dev/null 2>&1; then", "         ; then"),
    ("rollback: reloads", '        echo "rolled back (config restored, not reloaded)" >&2', "        ssh \"$host\" 'sudo -n /usr/bin/systemctl reload nginx'; echo \"rolled back (config restored, not reloaded)\" >&2"),
    ("rollback: exit 0", "      fi\n      exit 1\n    fi ;;", "      fi\n      exit 0\n    fi ;;"),
    ("rollback: added files not listed", '--diff-filter=A HEAD~1 HEAD -- etc-nginx 2>/dev/null)', '--diff-filter=M HEAD~1 HEAD -- etc-nginx 2>/dev/null)'),
    ("cert: no name check", '-*|.*|*..*|*[!A-Za-z0-9.-]*) echo', 'NEVERMATCH) echo'),
    ("cert: leading dash allowed", '-*|.*|*..*|*[!A-Za-z0-9.-]*) echo', '.*|*..*|*[!A-Za-z0-9.-]*) echo'),
    ("cert: no suffix", '*) n=$n.$dom;; esac', '*) ;; esac'),
    ("cert: pull even on failure", 'claude-cert $n" && pull', 'claude-cert $n"; pull'),
    ("help: code lines shown", "sed -n '2,/^[^#]/p' \"$0\" | grep '^#'", "sed -n '2,/^[^#]/p' \"$0\""),
    ("unknown command exits 0", '""|help|-h|--help) exit 0;; *) exit 2;;', '*) exit 0;;'),
    ("default host changed", 'host=${PROXY_HOST:-$("$pg" network.hosts.web_vm)}', 'host=${PROXY_HOST:-web@192.0.2.21}'),
    ("default mirror changed", 'm=${PROXY_MIRROR:-$HOME/opt/nginx-mirror}', 'm=${PROXY_MIRROR:-$HOME/opt/nginx}'),
    ("missing mirror goes on", 'cd "$m" || exit 1', 'cd "$m"'),
]
